{
  "results": [
    {
      "n": "G1",
      "evidence": "Screenshots 1–5 show the 3D bamboo scene rendering cleanly in Chrome with no errors or blank screen.",
      "pass": true
    },
    {
      "n": "G2",
      "evidence": "OrbitControls sets maxDistance to 45 without clamping maxPolarAngle, allowing the camera to orbit below the ground plane (y = -0.35) and zoom completely outside the grove into white fog as seen in screenshot 5.",
      "pass": false
    },
    {
      "n": "G3",
      "evidence": "The scene uses two InstancedMesh calls (340 stalks, 3400 leaf planes), one 2048x2048 shadow map, and an EffectComposer with UnrealBloomPass, which runs comfortably above 30 fps on integrated graphics.",
      "pass": true
    },
    {
      "n": "1",
      "evidence": "Screenshots 1–5 display a bottom-left UI bar containing helper text and three interactive buttons ('Match Photo Angle', 'Ground Walk View', 'Wind: ON').",
      "pass": false
    },
    {
      "n": "2",
      "evidence": "In the animate() loop, windUniforms.uTime updates automatically from clock.getElapsedTime() with windOn = true by default, driving vertex shader sway on stalks and leaves.",
      "pass": true
    },
    {
      "n": "3",
      "evidence": "Screenshot 1 matches the reference photo's upward wide-angle perspective, converging foreground bamboo stalks, and dark overhanging branch in the upper left.",
      "pass": true
    },
    {
      "n": "4",
      "evidence": "Screenshots 1–3 show foreground and mid-ground stalk spacing similar to the reference photo, though background density fades quickly into bright white fog.",
      "pass": true
    },
    {
      "n": "5",
      "evidence": "Screenshots 1–3 appear washed out with bright white fog and pale desaturated greens, lacking the rich yellow-green to deep shadowed forest greens of the reference photo.",
      "pass": false
    },
    {
      "n": "6",
      "evidence": "The reference photo looks strictly upward into the canopy and contains no ground elements such as a path or brushwood fence, and the 3D scene likewise has only a flat dark circle for the floor.",
      "pass": false
    },
    {
      "n": "7",
      "evidence": "Screenshot 1 shows bright overhead backlighting similar in direction to the reference photo, though heavy bloom and white fog make the scene much brighter and hazier than the photo.",
      "pass": false
    },
    {
      "n": "8",
      "evidence": "Screenshots 1–3 clearly show dark horizontal node rings with slight geometric bulges spaced at regular intervals along every bamboo stalk.",
      "pass": true
    },
    {
      "n": "9",
      "evidence": "Screenshots 1–3 and the procedural placement loop (scaleR from 0.68 to 1.23, scaleY from 0.82 to 1.14) show varied stalk thicknesses and heights.",
      "pass": true
    },
    {
      "n": "10",
      "evidence": "Screenshots 1–3 show stalks leaning at varied natural angles rather than standing on a strict vertical grid.",
      "pass": true
    },
    {
      "n": "11",
      "evidence": "Screenshots 1 and 4 show the canopy composed of clusters of thin, narrow lanceolate leaves on textured planes.",
      "pass": true
    },
    {
      "n": "12",
      "evidence": "In section 9 of the code, the ground is a single flat CircleGeometry with a solid dark green MeshStandardMaterial (0x1a2616) and no soil texture or fallen leaves.",
      "pass": false
    },
    {
      "n": "13",
      "evidence": "Screenshot 5 shows the entire circular grove ending abruptly in empty white space when zoomed out, and screenshots 1–3 show open white sky/fog gaps around the sides.",
      "pass": false
    },
    {
      "n": "14",
      "evidence": "leafInstanced does not have castShadow enabled in the code, and screenshots 1–3 show smooth uniform highlights along the stalks rather than dappled sunlight patches.",
      "pass": false
    },
    {
      "n": "15",
      "evidence": "Screenshots 1–3 show atmospheric haze/fog and bloom creating brightness gradients and depth separation between foreground and background stalks.",
      "pass": true
    },
    {
      "n": "16",
      "evidence": "Leaf materials use emissive green maps and bright HSL colors up high, giving leaves a bright green look in screenshots 1 and 4, though it reads more as flat unlit green in screenshot 4 than realistic light transmission.",
      "pass": false
    },
    {
      "n": "17",
      "evidence": "Screenshots 1–4 show soft dark green shadows between stalks and foliage that never clip to pure black.",
      "pass": true
    },
    {
      "n": "18",
      "evidence": "Screenshots 1–3 show strong specular highlights on the stalks, but the surface looks overly smooth and plastic-like with uniform green coloring rather than natural yellowing and organic stains.",
      "pass": false
    },
    {
      "n": "19",
      "evidence": "In screenshot 4, the leaves appear as opaque, flat-shaded bright green cutouts with visible alpha-tested edges rather than translucent foliage.",
      "pass": false
    },
    {
      "n": "20",
      "evidence": "The ground mesh is an untextured solid-color circle (color: 0x1a2616), which does not read as real soil, leaves, or stone.",
      "pass": false
    },
    {
      "n": "21",
      "evidence": "The camera looks sharply upward so verticals naturally converge toward the zenith without any unintended Dutch tilt or horizon roll (camera up vector remains default Y-up).",
      "pass": true
    },
    {
      "n": "22",
      "evidence": "In leafMat.onBeforeCompile, vertex positions are displaced horizontally using sin(uTime) terms for canopySway and flutter.",
      "pass": true
    },
    {
      "n": "23",
      "evidence": "In bambooMat.onBeforeCompile, horizontal wind displacement is multiplied by pow(hFactor, 2.1) where hFactor = clamp(transformed.y / 28.0, 0.0, 1.0), bending stalks more at the top than at the base.",
      "pass": true
    },
    {
      "n": "24",
      "evidence": "The wind shader uses only fixed-amplitude sine/cosine waves (sin(uTime * 0.85 + phase) * 0.32 + sin(uTime * 1.9 + phase * 1.7) * 0.08) with constant uWindStrength = 1.0, rather than varied gusts.",
      "pass": false
    },
    {
      "n": "25",
      "evidence": "Neither the screenshots nor the HTML source contain any particle system, falling leaves, or drifting dust.",
      "pass": false
    },
    {
      "n": "26",
      "evidence": "The vertex shader animations use continuous trigonometric functions of elapsed time (frequencies 0.72 to 2.4 rad/s and gentle amplitudes of 0.14–0.32m), running smoothly at real-world speed with no loop resets.",
      "pass": true
    },
    {
      "n": "27",
      "evidence": "Stalks share one procedural texture and curve geometry, and in screenshots 1–3 adjacent stalks show identical repeating horizontal node spacing and glossy linear highlights.",
      "pass": false
    },
    {
      "n": "28",
      "evidence": "All geometry is static instanced meshes without LOD switching, billboard flipping, or transparent depth-sorting issues (alphaTest is used), preventing pop-in or flicker during orbit.",
      "pass": true
    },
    {
      "n": "29",
      "evidence": "Leaf planes (2.7x2.7m) are randomly scattered around canopyAnchorPoints without collision avoidance, causing leaf planes and stems to intersect stalks as seen in screenshots 1 and 4.",
      "pass": false
    },
    {
      "n": "30",
      "evidence": "Screenshot 1 has an obvious CG appearance due to blown-out white fog, shiny plastic-like specular streaks on the bamboo, and an on-screen UI bar, so it could not pass for the reference photo.",
      "pass": false
    }
  ]
}
